namespace ghidra.app.util.navigation;



using ghidra.app.services;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

/**
 * Task for searching for symbols. All the logic for the search is done by the
 * {@link SymbolSearcher}.
 */
public class GoToSymbolSearchTask : Task {

	private QueryData queryData;
	private List<Program> searchPrograms;
	private List<ProgramLocation> results;
	private int limit;

	public GoToSymbolSearchTask(QueryData queryData, List<Program> searchPrograms, int limit) : base("Searching Symbols...")
    {
		this.queryData = queryData;
		this.searchPrograms = searchPrograms;
		this.limit = limit;
	}

	/* @Override */
	public void run(TaskMonitor monitor)
    {
		SymbolSearcher searcher = new SymbolSearcher(queryData, limit, monitor);
		results = searcher.findMatchingSymbolLocations(searchPrograms);
	}

	public List<ProgramLocation> getResults() {
		return results;
	}

}
